package com.ftk.tpip.catalog.domain.model;import static org.junit.jupiter.api.Assertions.*;import com.ftk.tpip.shared.*;import org.junit.jupiter.api.Test;
class CanonicalContractTest{@Test void createsStableRequestContract(){var c=CanonicalContract.create(2,AssetCode.of("payment.refund.request"),"Refund Request",ContractKind.REQUEST,null);assertEquals(CanonicalContractStatus.ACTIVE,c.status());assertEquals(ContractKind.REQUEST,c.contractKind());}@Test void createsImmutableDraftVersion(){var v=CanonicalContractVersion.draft(1,SemanticVersion.parse("1.0.0"),SchemaStandard.JSON_SCHEMA_2020_12,"{\"type\":\"object\"}",null,CompatibilityMode.BACKWARD,"a".repeat(64));assertEquals(CanonicalContractLifecycleStatus.DRAFT,v.lifecycleStatus());assertEquals(0,v.versionNo());}}
